def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cy = cx = None
    for r0, row in enumerate(grid):
        for c0, value in enumerate(row):
            if value == 3:
                cy, cx = r0, c0
                break
        if cy is not None:
            break
    if cy is None:
        return out

    r, c = cy, cx

    def move(dr, dc, steps):
        nonlocal r, c
        for _ in range(steps):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == 2:
                    return False
                out[nr][nc] = 3
            r, c = nr, nc
        return True

    radius = 2
    while radius <= 2 * (h + w):
        if not move(-1, 0, 2):
            break
        if not move(0, 1, 2 * radius - 2):
            break
        if not move(1, 0, 2 * radius):
            break
        if not move(0, -1, 2 * radius):
            break
        if not move(-1, 0, 2 * radius):
            break
        radius += 2
    return out
